  Lemma window_store_ok : forall vals ebs MV kn (z : Z) (m : nat),
    let E := Env (vals_ev vals) ebs in
    know_ok ASEGS E MV kn -> has_window kn = true -> vals_ev vals 0 = sp0 ->
    - 8388608 <= z -> z + Z.of_nat m <= 0 ->
