  Definition STKTOP : Z := Z.max (ar_sptop ar) (ar_stack_top ar).
  Lemma stksh_rng : forall LB FF LK cr A M V x, ri_inv HI LB FF LK cr A M V -> in_shadow_of (ahl_ceil ar) (STKTOP - ahl_ceil ar) x ->
